/**
 * Clean, structured data generated by `npm run import:rym` from a saved
 * RateYourMusic yearly-list page. This is the import layer only: a later step
 * combines it with hand-authored data (accent, Brazilian Portuguese intro,
 * exact streaming links, local artwork) to produce the site's `YearData`.
 */

export interface ImportedRatingBucket {
	/** RateYourMusic star rating, 0–5 in half steps. */
	rating: number;
	/** English label as written on RYM, e.g. "Masterpieces". */
	labelEn?: string;
	/** Count exactly as stated in the list description. Percentages are derived, never stored. */
	count: number;
}

export interface ImportedAlbum {
	rank: number;
	/**
	 * Stable id derived from artist + album (see `assignAlbumSlugs`). Artwork files and
	 * manual overrides are keyed by it, so ranks can change without breaking references.
	 */
	slug: string;
	artist: string;
	album: string;
	releaseYear?: number;
	rymUrl?: string;
	primaryGenres: string[];
	secondaryGenres: string[];
	descriptors: string[];
	/** Search URL fallback until an exact album link is supplied during enrichment. */
	spotifyUrl: string;
	/** Search URL fallback until an exact album link is supplied during enrichment. */
	appleMusicUrl: string;
	streamingLinksAreSearchFallbacks: true;
	/**
	 * Import metadata only: the artwork reference found in the saved page
	 * (a path into the page's `*_files` folder or a CDN URL). Not used by the site.
	 */
	artworkSource?: string;
	/**
	 * Production artwork written by `npm run enrich:artwork`: a public site path
	 * under `/artwork/{year}/`. Absent until enrichment succeeds for the album.
	 */
	artwork?: string;
}

export interface ImportedYearData {
	year: number;
	listTitle: string;
	rymListUrl: string;
	/** Editorial introduction paragraphs, without rating or playlist lines. */
	introEn: string[];
	/** Stated total exactly as written. Authoritative denominator for percentages. */
	totalAlbumsRated: number;
	/** Ordered from the highest rating to the lowest. */
	ratingDistribution: ImportedRatingBucket[];
	spotifyPlaylistUrl?: string;
	/** Sorted by ascending rank. */
	albums: ImportedAlbum[];
	importMeta: {
		source: 'rym-saved-html';
		/** Basename of the saved page the data came from. */
		sourceFile: string;
		/** Album count implied by the list title ("Top 20"), when present. */
		expectedAlbumCount?: number;
		/** Non-fatal validation findings from the import run. */
		warnings: string[];
	};
}
